insert into public.curriculum_releases(id,release_key,subject_program_id,release_number,version_label,status,provenance_quality,reconciliation_id,source_snapshot,content_fingerprint,effective_from,notes) select '44e5e99a-43bc-5937-8793-b2c614e38700'::uuid,'physics7_u06_2026_08_14_draft_r6',id,6,'Ֆիզիկա 7 — Գլուխ VI. բովանդակության վերանայման թեկնածու','draft','exact','d47c56a2-736e-591d-bb06-26c9776fe1a5'::uuid,'{"textbook":{"title":"Ֆիզիկա 7","authors":["Գագիկ Մելիքյան","Սոս Մաիլյան"],"publisher":"Էդիթ Պրինտ","year":2023,"library_file_id":"libfile_f4cf0be21a6081919cd90c8922b5396d","sha256":"d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904","sections":[40,55],"printed_pages":[118,163],"pdf_pages":[119,164]},"programme":{"act_url":"https://www.arlis.am/hy/acts/229331","attachment_url":"https://www.arlis.am/acts/files/363077/966f79b4570fa3c6cee0263bd3776ac4aff0fcea6242d2c48121256309f53478","sha256":"966f79b4570fa3c6cee0263bd3776ac4aff0fcea6242d2c48121256309f53478","bytes":248283,"theme":6,"outcome_locator":"DOCX table 6, row 5, cell 0 (zero-based)","legal_version":"N 40-Ն as amended by N 36-Ն; incorporation effective 2026-08-14","source_reused_from_verified_2026_10_18_download":true,"raw_outcome_cell":"Թեմայի նպատակին հասնելու համար սովորողը պետք է կարողանա՝\n1.Պարտադիր\nներկայացնել ճնշման ֆիզիկական իմաստը և հաշվարկել այն պարզ իրավիճակներում,(Հ4,Հ7,Հ9)\nներկայացնել ճնշման մեծացման և փոքրացման եղանակները, բերել օրինակներ, (Հ4,Հ9)\nբացատրել առօրյա կյանքում գազի և հեղուկի ճնշման դերը, (Հ29,Հ30)\nներկայացնել Պասկալի և հաղորդակից անոթների օրենքները և կիրառել դրանք պարզ իրավիճակներում,(Հ9)\nնկարագրել ջրաբաշխական մամլիչի կառուցվածքը, աշխատանքի սկզբունքը և կիրառությունները, կատարել հաշվարկներ ուժի շահումը որոշելու համար,(Հ10,Հ29)\nփորձի միջոցով հիմնավորել մթնոլորտային ճնշման գոյությունը, բացատրել դրա առաջացման պատճառը,   (Հ4,Հ28)\nբերել արքիմեդյան ուժի դրսևորման օրինակներ, (Հ9)\nներկայացնել Արքիմեդի օրենքը,(Հ9)\nնախագծել և իրականացնել հեղուկներում և գազերում արքիմեդյան ուժի որոշման փորձեր,(Հ4,Հ28,Հ29)\nարտածել հեղուկներում մարմինների լողալու պայմանները,(Հ9)\nներկայացնել արքիմեդյան ուժի դրսևորումները կենդանական աշխարհում,     նավագնացության և օդագնացության ոլորտներում:(Հ29,Հ30,Հ31)\n2.Լրացուցիչ\n1) նշել ճնշման առաջացման մեխանիզմները պինդ, հեղուկ և գազային մարմիններում,\n2) բացատրել անոթի պատերի վրա ազդող գազի և հեղուկի ճնշման պատճառը,\n3) չափել գազի և հեղուկի ճնշումը,\n4) նկարագրել մխոցավոր հեղուկային պոմպի աշխատանքը"},"ownerPlanAcceptance":"2026-10-19T19:54:22+04:00","ownerPlanAcceptanceScope":{"skills":16,"candidateCeiling":242,"batchSizes":[70,90,82],"nonGatingSkills":["PHY7-U06-S13","PHY7-U06-S14","PHY7-U06-S15","PHY7-U06-S16"],"practicalRecords":5},"gasBuoyancyScopeDecision":{"at":"2026-10-19","procedure":"excluded","teacherObservedWorkflow":"excluded","knowledgeOnly":true,"performedWorkClaim":false,"evidence":"docs/evidence/chapter-vi-gas-buoyancy-scope-decision-20261019.json"},"governingSourceBinding":"existing Physics 7 governing sources; textbook supporting only","readinessContract":"not created","proposedPrerequisites":"conceptual only; not runtime edges"}'::jsonb,md5('{"textbook":{"title":"Ֆիզիկա 7","authors":["Գագիկ Մելիքյան","Սոս Մաիլյան"],"publisher":"Էդիթ Պրինտ","year":2023,"library_file_id":"libfile_f4cf0be21a6081919cd90c8922b5396d","sha256":"d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904","sections":[40,55],"printed_pages":[118,163],"pdf_pages":[119,164]},"programme":{"act_url":"https://www.arlis.am/hy/acts/229331","attachment_url":"https://www.arlis.am/acts/files/363077/966f79b4570fa3c6cee0263bd3776ac4aff0fcea6242d2c48121256309f53478","sha256":"966f79b4570fa3c6cee0263bd3776ac4aff0fcea6242d2c48121256309f53478","bytes":248283,"theme":6,"outcome_locator":"DOCX table 6, row 5, cell 0 (zero-based)","legal_version":"N 40-Ն as amended by N 36-Ն; incorporation effective 2026-08-14","source_reused_from_verified_2026_10_18_download":true,"raw_outcome_cell":"Թեմայի նպատակին հասնելու համար սովորողը պետք է կարողանա՝\n1.Պարտադիր\nներկայացնել ճնշման ֆիզիկական իմաստը և հաշվարկել այն պարզ իրավիճակներում,(Հ4,Հ7,Հ9)\nներկայացնել ճնշման մեծացման և փոքրացման եղանակները, բերել օրինակներ, (Հ4,Հ9)\nբացատրել առօրյա կյանքում գազի և հեղուկի ճնշման դերը, (Հ29,Հ30)\nներկայացնել Պասկալի և հաղորդակից անոթների օրենքները և կիրառել դրանք պարզ իրավիճակներում,(Հ9)\nնկարագրել ջրաբաշխական մամլիչի կառուցվածքը, աշխատանքի սկզբունքը և կիրառությունները, կատարել հաշվարկներ ուժի շահումը որոշելու համար,(Հ10,Հ29)\nփորձի միջոցով հիմնավորել մթնոլորտային ճնշման գոյությունը, բացատրել դրա առաջացման պատճառը,   (Հ4,Հ28)\nբերել արքիմեդյան ուժի դրսևորման օրինակներ, (Հ9)\nներկայացնել Արքիմեդի օրենքը,(Հ9)\nնախագծել և իրականացնել հեղուկներում և գազերում արքիմեդյան ուժի որոշման փորձեր,(Հ4,Հ28,Հ29)\nարտածել հեղուկներում մարմինների լողալու պայմանները,(Հ9)\nներկայացնել արքիմեդյան ուժի դրսևորումները կենդանական աշխարհում,     նավագնացության և օդագնացության ոլորտներում:(Հ29,Հ30,Հ31)\n2.Լրացուցիչ\n1) նշել ճնշման առաջացման մեխանիզմները պինդ, հեղուկ և գազային մարմիններում,\n2) բացատրել անոթի պատերի վրա ազդող գազի և հեղուկի ճնշման պատճառը,\n3) չափել գազի և հեղուկի ճնշումը,\n4) նկարագրել մխոցավոր հեղուկային պոմպի աշխատանքը"},"ownerPlanAcceptance":"2026-10-19T19:54:22+04:00","ownerPlanAcceptanceScope":{"skills":16,"candidateCeiling":242,"batchSizes":[70,90,82],"nonGatingSkills":["PHY7-U06-S13","PHY7-U06-S14","PHY7-U06-S15","PHY7-U06-S16"],"practicalRecords":5},"gasBuoyancyScopeDecision":{"at":"2026-10-19","procedure":"excluded","teacherObservedWorkflow":"excluded","knowledgeOnly":true,"performedWorkClaim":false,"evidence":"docs/evidence/chapter-vi-gas-buoyancy-scope-decision-20261019.json"},"governingSourceBinding":"existing Physics 7 governing sources; textbook supporting only","readinessContract":"not created","proposedPrerequisites":"conceptual only; not runtime edges"}'::jsonb::text),effective_from,'Chapter VI authoring scope only. No predecessor, active policy, pools, forms, blueprints, model binding or learner release. Ordinary review, assessment-contract and specialist gates remain open.' from public.subject_programs where id=(select subject_program_id from public.units where code='PHY7-U02');
