insert into public.curriculum_release_outcomes(curriculum_release_id,learning_outcome_id,source_document_id,official_code_snapshot,statement_hy_snapshot,statement_en_snapshot,source_locator_snapshot,requirement_level_snapshot,source_transcription_notes_snapshot,framework_references_snapshot,subject_standard_references_snapshot,mapping_notes_snapshot,sequence_order_snapshot) select '44e5e99a-43bc-5937-8793-b2c614e38700'::uuid,o.id,o.source_document_id,o.official_code,o.statement_hy,o.statement_en,o.source_locator,o.requirement_level,o.source_transcription_notes,m.framework_references,m.subject_standard_references,m.mapping_notes,o.sequence_order from public.learning_outcomes o join public.learning_outcome_normative_mappings m on m.learning_outcome_id=o.id and m.reconciliation_id='d47c56a2-736e-591d-bb06-26c9776fe1a5'::uuid;
insert into public.curriculum_release_skills(curriculum_release_id,skill_id,skill_code_snapshot,name_hy_snapshot,name_en_snapshot,description_hy_snapshot,description_en_snapshot,layer_snapshot,sequence_order_snapshot,disposition_snapshot,rationale_snapshot,outcome_mapping_snapshot) select '44e5e99a-43bc-5937-8793-b2c614e38700'::uuid,s.id,s.code,s.name_hy,s.name_en,s.description_hy,s.description_en,s.layer::text,s.sequence_order,r.disposition,r.rationale,(select jsonb_agg(jsonb_build_object('learningOutcomeId',m.learning_outcome_id,'mappingType',m.mapping_type,'rationale',m.rationale) order by m.learning_outcome_id) from public.skill_outcome_curriculum_mappings m where m.skill_id=s.id and m.reconciliation_id='d47c56a2-736e-591d-bb06-26c9776fe1a5'::uuid) from public.skills s join public.skill_curriculum_reconciliations r on r.skill_id=s.id and r.reconciliation_id='d47c56a2-736e-591d-bb06-26c9776fe1a5'::uuid;
